def main():
    from transformers import AutoTokenizer,AddedToken
    ROOT.mkdir(exist_ok=True)
    if(ROOT/'frozen.json').exists():raise SystemExit('Codec course already frozen')
    source=BUILD/'composition-v1/server-results';rng=random.Random(6114501);em=Emulator()
    training=read(source/'course/train.jsonl')+read(source/'phase4-extra-train.jsonl')
    replay=read(source/'course/formal-replay.jsonl')
    replay += [r for r in read(BUILD/'training/sft-combined-v2.jsonl')if r['kind']in ['repair_after_failure','repair_after_trace','finish_after_pass','trace_call']][:3000]
    replay+=read(source/'phase4-feedback.jsonl')
    save_jsonl(ROOT/'train.jsonl',training);save_jsonl(ROOT/'replay.jsonl',replay)
    for level in [1,2,3]:save_jsonl(ROOT/f'development{level}.jsonl',read(source/f'development{level}.jsonl')+read(source/f'fresh{level}.jsonl'))
    save_jsonl(ROOT/'formal-development.jsonl',read(source/'course/formal-development.jsonl'))
    teacher=read(source/'course/validation.jsonl');groups=collections.defaultdict(list)
    for t in teacher:groups[(t['level'],t['expression'][0])].append(t)
    save_jsonl(ROOT/'teacher-development.jsonl',[t for (level,op),rows in groups.items()if level in [2,3]for t in rows[:7]])
    codebook=json.loads((source/'codec-study/codebook-32.json').read_text())
    (ROOT/'codebook-32.json').write_text(json.dumps(codebook,indent=2)+'\n')
    old_tokenizer=AutoTokenizer.from_pretrained(source/'export/small/hf',local_files_only=True,trust_remote_code=False)
    tokenizer=AutoTokenizer.from_pretrained(source/'export/small/hf',local_files_only=True,trust_remote_code=False)
    assert len(tokenizer)==OLD_VOCAB
    assert tokenizer.add_tokens([AddedToken(x,normalized=False,special=False)for x in TAGS])==32
    assert tokenizer.convert_tokens_to_ids(TAGS)==list(range(OLD_VOCAB,OLD_VOCAB+32))
    tokenizer.model_max_length=2048;tokenizer.save_pretrained(ROOT/'tokenizer')
    for t in training:
        assert tokenizer.encode(t['task'],add_special_tokens=False)==old_tokenizer.encode(t['task'],add_special_tokens=False)
    forbidden={normalize(x['task'])for name in ['train','development1','development2','development3']for x in read(ROOT/(name+'.jsonl'))}
    fresh={1:[],2:[],3:[]}
    for op,texts in SIMPLE.items():
        a,b=rng.sample(['R0','R1','R2','R3'],2);expr=[op,a,b]if op in ['+','-','*','/']else[op,a]
        for j,text in enumerate(texts):fresh[1].append(make_task(text.format(a=a,b=b),expr,rng,f'codec-new1:{op}:{j}',split='fresh',emulator=em))
    for level,library in [(2,TWO),(3,THREE)]:
        for i,(expr,texts)in enumerate(library):
            names=rng.sample(['R0','R1','R2','R3'],4);mapping=dict(zip('ABCD',names));values=dict(zip('abcd',names))
            for j,text in enumerate(texts):fresh[level].append(make_task(text.format(**values),substitute(expr,mapping),rng,f'codec-new{level}:{i}:{j}',split='fresh',emulator=em))
    for level,rows in fresh.items():
        assert all(normalize(t['task'])not in forbidden for t in rows),'New wording overlaps observed course'
        save_jsonl(ROOT/f'fresh{level}.jsonl',rows)
    for mode in MODES:
        p=Protocol(mode,codebook);ids=set([tokenizer.eos_token_id])
        targets=[answer(t)for t in training]+[r['answer']for r in replay]
        import re
        targets=[re.sub(r'<plan>.*?</plan>','',x,flags=re.S)for x in targets]
        for target in targets:ids.update(tokenizer.encode(p.encode_text(target),add_special_tokens=False))
        # Protocol/control coverage is not restricted to observed opcodes.
        if mode=='hex':ids.update(json.loads((source/'codec-study/output-token-ids.json').read_text()))
        else:
            ids.update(range(OLD_VOCAB,OLD_VOCAB+32))
            for text in ['<write>','</write>','<run/>','<trace/>','<done/>']:
                ids.update(tokenizer.encode(text,add_special_tokens=False))
        (ROOT/f'output-{mode}.json').write_text(json.dumps(sorted(ids))+'\n')
        assert len(ids)<128,(mode,len(ids))
    policy={'steps_each':8000,'effective_batch':32,'contexts':[512,1024,2048],'context_probabilities':[.8,.1,.1],
      'quantization':'Q4 group32 from first update','primary_comparison':'Fixed8000-update endpoints; no fresh-based selection',
      'secondary_comparison':'Best validation checkpoint per variant; all choices frozen before new audit',
      'common_initial_embeddings':'Both HEX and H32 have identical32 added rows; old8192 Russian token IDs unchanged',
      'input_code_fields':'H32 current-code and trace opcodes; same lossless decoder at emulator boundary',
      'output_projection':'Format-specific compact row subset; public language replay projects old8192 rows',
      'warmup_first1000':{'formal_tool':.25,'language':.1,'simple':.15,'formula_to_code':.5},
      'later':{'formal_tool':.25,'language':.05,'simple':.25,'two_three_op':.45},
      'natural_kinds':{'parse_semantic':.2,'parse':.15,'program':.5,'compile':.05,'repair':.06,'trace_repair':.03,'done':.01},
      'lr':4e-5,'embedding_lr_factor':.5,'warmup_updates':200,'cosine_floor':.25,'weight_decay':.01,
      'standard_program_bytes':105,'extended_memory_enabled':False,'reasoning_prefix_retained':True,
      'teacher_new_data':False,'all_variants_parallel':True,'gpu_assignment':{'champion-hex':0,'champion-h32':0,'small-hex':1,'small-h32':1},
      'new_audit_scope':'New Codex-authored Russian wordings of known one/two/three-op arithmetic; not a human study or new mathematical structures'}
    (ROOT/'policy.json').write_text(json.dumps(policy,ensure_ascii=False,indent=2)+'\n')
    frozen={'files':{p.name:{'sha256':sha(p),'rows':len(read(p))if p.suffix=='.jsonl'else None}for p in ROOT.iterdir()if p.is_file()and p.suffix in ['.json','.jsonl']},
      'source_packets':{arm:json.loads((source/f'export/{arm}/manifest.json').read_text())['packed_sha256']for arm in ARMS},
      'source_masters':{arm:sha(source/f'export/{arm}/hf/model.safetensors')for arm in ARMS},
      'source_tokenizer_sha256':sha(source/'export/small/hf/tokenizer.json'),'input_russian_ids_preserved_for_all_training_tasks':True,
      'new_token_ids':{tag:OLD_VOCAB+i for i,tag in enumerate(TAGS)},'before_gradients':True,
      'fresh_counts':{str(k):len(v)for k,v in fresh.items()},'huffman_fitted_on_previous_training_only':True}
    (ROOT/'frozen.json').write_text(json.dumps(frozen,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'fresh':frozen['fresh_counts'],'train':len(training),'replay':len(replay),
      'output_rows':{m:len(json.loads((ROOT/f'output-{m}.json').read_text()))for m in MODES}},ensure_ascii=False))


if __name__=='__main__':main()
